#!/usr/bin/env bash
# check.sh — machine-checkable completion gate for shell-sum-range-fix.
# Exit 0 = the fix is correct. Do NOT edit this file; the semantic
# assertion verifies it is unchanged.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

check() {
  local n="$1" want="$2" got
  got="$(bash "$HERE/sum_range.sh" "$n")"
  if [[ "$got" != "$want" ]]; then
    echo "FAIL: sum_range.sh $n = $got, want $want" >&2
    exit 1
  fi
}

check 1 1
check 5 15
check 10 55
check 100 5050
echo "ok"
